function setup(basePath: string) {
  const server = { config: { base: basePath, logger: { error: vi.fn() } } } as unknown as ViteDevServer
  let middlewares = new Hono<ViteEnv, BlankSchema, '/'>()
  const dispatchApp = middlewares // what handle(middlewares) keeps
  if (basePath !== '/') {
    middlewares = middlewares.basePath(basePath) as typeof middlewares
  }
  middlewares.use('*', async (_c, next) => {
    await next()
  })
  middlewares.use('*', async () => {
    throw new Error('transform failed')
  })
  middlewares.onError(errorMiddleware(server, false))
  return { dispatchApp, server }
}

// Non-root basePath, as in Vrowzer: Hono's default handler answers
const preview = setup('/__preview__/')
const res = await preview.dispatchApp.request('/__preview__/x')
expect(res.status).toBe(500)
expect(await res.text()).toBe('Internal Server Error')
expect(preview.server.config.logger.error).not.toHaveBeenCalled()

// basePath '/': errorMiddleware runs, throws, and the request rejects
